#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

#define MAXLOG 20

typedef struct Edge {
    int to, next;
    int color;
    ll len;
} Edge;

typedef struct QueryItem {
    int color;
    ll y;
    int idx;
    int sign;   // +1 or -1
    int next;
} QueryItem;

typedef struct Pair {
    int color;
    int qid;
    ll y;
    int sign;
} Pair;

static int N, Q;
static Edge *edges;
static int *head;
static int edge_cnt = 0;

static int *depthv;
static int **up;
static int *tin, *tout, timer2 = 0;
static ll *distRoot;

static int *qhead;
static QueryItem *qitems;
static int qcnt = 0;

static ll *ans;

/* add undirected edge */
static void add_edge(int u, int v, int color, ll len) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].color = color;
    edges[edge_cnt].len = len;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;

    edges[edge_cnt].to = u;
    edges[edge_cnt].color = color;
    edges[edge_cnt].len = len;
    edges[edge_cnt].next = head[v];
    head[v] = edge_cnt++;
}

static void add_query_item(int node, int color, ll y, int idx, int sign) {
    qitems[qcnt].color = color;
    qitems[qcnt].y = y;
    qitems[qcnt].idx = idx;
    qitems[qcnt].sign = sign;
    qitems[qcnt].next = qhead[node];
    qhead[node] = qcnt++;
}

/* iterative DFS to compute tin/tout, depth, parent table, distRoot */
static void build_lca_and_dist() {
    int *stack_v = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_p = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_ei = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_state = (int*)malloc((2 * N + 5) * sizeof(int));
    int top = 0;

    stack_v[top] = 1;
    stack_p[top] = 0;
    stack_ei[top] = head[1];
    stack_state[top] = 0;
    top++;

    depthv[1] = 0;
    distRoot[1] = 0;
    up[0][1] = 0;

    while (top) {
        int idx = top - 1;
        int v = stack_v[idx];
        int p = stack_p[idx];

        if (stack_state[idx] == 0) {
            stack_state[idx] = 1;
            tin[v] = ++timer2;
            for (int k = 1; k < MAXLOG; k++) {
                up[k][v] = up[k-1][ up[k-1][v] ];
            }
        }

        int ei = stack_ei[idx];
        while (ei != -1 && edges[ei].to == p) ei = edges[ei].next;

        if (ei == -1) {
            tout[v] = timer2;
            top--;
            continue;
        }

        stack_ei[idx] = edges[ei].next;
        int to = edges[ei].to;
        up[0][to] = v;
        depthv[to] = depthv[v] + 1;
        distRoot[to] = distRoot[v] + edges[ei].len;

        stack_v[top] = to;
        stack_p[top] = v;
        stack_ei[top] = head[to];
        stack_state[top] = 0;
        top++;
    }

    free(stack_v);
    free(stack_p);
    free(stack_ei);
    free(stack_state);
}

static int is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[v] <= tout[u];
}

static int lca(int a, int b) {
    if (is_ancestor(a, b)) return a;
    if (is_ancestor(b, a)) return b;
    for (int k = MAXLOG - 1; k >= 0; k--) {
        int x = up[k][a];
        if (x != 0 && !is_ancestor(x, b)) a = x;
    }
    return up[0][a];
}

static int cmp_pair(const void *A, const void *B) {
    const Pair *a = (const Pair*)A;
    const Pair *b = (const Pair*)B;
    if (a->color != b->color) return (a->color < b->color) ? -1 : 1;
    if (a->qid != b->qid) return (a->qid < b->qid) ? -1 : 1;
    return 0;
}

int main(void) {
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    head = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    edges = (Edge*)malloc((2 * (N - 1)) * sizeof(Edge));

    for (int i = 0; i < N - 1; i++) {
        int a, b, c;
        ll d;
        scanf("%d %d %d %lld", &a, &b, &c, &d);
        add_edge(a, b, c, d);
    }

    depthv = (int*)calloc(N + 1, sizeof(int));
    distRoot = (ll*)calloc(N + 1, sizeof(ll));
    tin = (int*)calloc(N + 1, sizeof(int));
    tout = (int*)calloc(N + 1, sizeof(int));

    up = (int**)malloc(MAXLOG * sizeof(int*));
    for (int k = 0; k < MAXLOG; k++) {
        up[k] = (int*)calloc(N + 1, sizeof(int));
    }

    build_lca_and_dist();

    qhead = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) qhead[i] = -1;

    qitems = (QueryItem*)malloc((3 * Q + 5) * sizeof(QueryItem));
    ans = (ll*)calloc(Q, sizeof(ll));

    Pair *pairs = (Pair*)malloc((3 * Q) * sizeof(Pair));
    int pcnt = 0;

    for (int i = 0; i < Q; i++) {
        int x, u, v;
        ll y;
        scanf("%d %lld %d %d", &x, &y, &u, &v);

        int w = lca(u, v);
        ans[i] = distRoot[u] + distRoot[v] - 2LL * distRoot[w];

        add_query_item(u, x, y, i, +1);
        add_query_item(v, x, y, i, +1);
        add_query_item(w, x, y, i, -2);

        pairs[pcnt++] = (Pair){x, i, y, +1};
        pairs[pcnt++] = (Pair){x, i, y, +1};
        pairs[pcnt++] = (Pair){x, i, y, -2};
    }

    qsort(pairs, pcnt, sizeof(Pair), cmp_pair);

    int *uniqColor = (int*)malloc((pcnt + 1) * sizeof(int));
    ll *qy = (ll*)malloc((pcnt + 1) * sizeof(ll));
    int *qsign = (int*)malloc((pcnt + 1) * sizeof(int));

    int m = 0;
    for (int i = 0; i < pcnt; ) {
        int color = pairs[i].color;
        int qid = pairs[i].qid;
        ll y = 0;
        int s = 0;
        while (i < pcnt && pairs[i].color == color && pairs[i].qid == qid) {
            y += pairs[i].y * pairs[i].sign;
            s += pairs[i].sign;
            i++;
        }
        if (s != 0) {
            uniqColor[m] = color;
            qy[m] = y / s;   /* same y in same query/color */
            qsign[m] = s;
            m++;
        }
    }

    free(pairs);

    /* For each color, maintain current count/sum on root->current path */
    int *colorCount = (int*)calloc(N + 1, sizeof(int));
    ll *colorSum = (ll*)calloc(N + 1, sizeof(ll));

    /* iterative DFS again to process queries */
    int *stack_v = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_p = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_ei = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_state = (int*)malloc((2 * N + 5) * sizeof(int));
    int *stack_ecolor = (int*)malloc((2 * N + 5) * sizeof(int));
    ll *stack_elen = (ll*)malloc((2 * N + 5) * sizeof(ll));
    int top = 0;

    stack_v[top] = 1;
    stack_p[top] = 0;
    stack_ei[top] = head[1];
    stack_state[top] = 0;
    stack_ecolor[top] = 0;
    stack_elen[top] = 0;
    top++;

    while (top) {
        int idx = top - 1;
        int v = stack_v[idx];
        int p = stack_p[idx];

        if (stack_state[idx] == 0) {
            stack_state[idx] = 1;

            for (int qi = qhead[v]; qi != -1; qi = qitems[qi].next) {
                int c = qitems[qi].color;
                ll replaced = (ll)colorCount[c] * qitems[qi].y;
                ll original = colorSum[c];
                ans[qitems[qi].idx] += (replaced - original) * qitems[qi].sign;
            }
        }

        int ei = stack_ei[idx];
        while (ei != -1 && edges[ei].to == p) ei = edges[ei].next;

        if (ei == -1) {
            if (p != 0) {
                int c = stack_ecolor[idx];
                ll d = stack_elen[idx];
                colorCount[c]--;
                colorSum[c] -= d;
            }
            top--;
            continue;
        }

        stack_ei[idx] = edges[ei].next;
        int to = edges[ei].to;
        int c = edges[ei].color;
        ll d = edges[ei].len;

        colorCount[c]++;
        colorSum[c] += d;

        stack_v[top] = to;
        stack_p[top] = v;
        stack_ei[top] = head[to];
        stack_state[top] = 0;
        stack_ecolor[top] = c;
        stack_elen[top] = d;
        top++;
    }

    for (int i = 0; i < Q; i++) {
        printf("%lld\n", ans[i]);
    }

    return 0;
}

