public class Main {
    static List<Edge>[] graph;
    static int N, LOG;
    static int[] depth, tin, tout;
    static long[] dist;
    static int[][] up;
    static int timer = 0;

    static class Edge {
        int to, color, len;
        Edge(int t, int c, int l) { to = t; color = c; len = l; }
    }

    static class BIT {
        int n;
        long[] tree;
        BIT(int n) { this.n = n; tree = new long[n+2]; }
        void add(int idx, long val) {
            for (; idx <= n; idx += idx & -idx) tree[idx] += val;
        }
        long sum(int idx) {
            long res = 0;
            for (; idx > 0; idx -= idx & -idx) res += tree[idx];
            return res;
        }
    }

    static List<BIT> sumBIT, cntBIT;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());
        LOG = (int)(Math.log(N)/Math.log(2)) + 1;

        graph = new ArrayList[N+1];
        for (int i = 1; i <= N; i++) graph[i] = new ArrayList<>();

        int maxColor = 0;
        for (int i = 0; i < N-1; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            int d = Integer.parseInt(st.nextToken());
            graph[a].add(new Edge(b, c, d));
            graph[b].add(new Edge(a, c, d));
            maxColor = Math.max(maxColor, c);
        }

        depth = new int[N+1];
        tin = new int[N+1];
        tout = new int[N+1];
        dist = new long[N+1];
        up = new int[LOG][N+1];

        // BIT per color (1..maxColor)
        sumBIT = new ArrayList<>();
        cntBIT = new ArrayList<>();
        for (int i = 0; i <= maxColor; i++) {
            sumBIT.add(new BIT(N*2));
            cntBIT.add(new BIT(N*2));
        }

        dfs(1, 0, 0, 0, 0);

        // fill binary lifting
        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= N; v++) {
                up[k][v] = up[k-1][up[k-1][v]];
            }
        }

        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int lca = lca(u, v);
            long origDist = dist[u] + dist[v] - 2*dist[lca];
            long sumOnPath = querySum(u, x) + querySum(v, x) - 2*querySum(lca, x);
            long cntOnPath = queryCnt(u, x) + queryCnt(v, x) - 2*queryCnt(lca, x);
            long newDist = origDist + (cntOnPath * y - sumOnPath);
            sb.append(newDist).append("\n");
        }
        System.out.print(sb);
    }

    static void dfs(int v, int p, int pColor, int pLen, int d) {
        depth[v] = d;
        up[0][v] = p;
        tin[v] = ++timer;
        if (p != 0) {
            sumBIT.get(pColor).add(tin[v], pLen);
            sumBIT.get(pColor).add(tout[p]+1, -pLen); // will adjust later? Actually we set tout after children.
            cntBIT.get(pColor).add(tin[v], 1);
            cntBIT.get(pColor).add(tout[p]+1, -1);
        }
        for (Edge e : graph[v]) {
            if (e.to == p) continue;
            dist[e.to] = dist[v] + e.len;
            dfs(e.to, v, e.color, e.len, d+1);
        }
        tout[v] = timer;
        // fix BIT: we added updates for edge v->parent at tin[v]; but tout[p] may not be known yet.
        // Better: after DFS we can add removal at tout[v]+1
        if (p != 0) {
            sumBIT.get(pColor).add(tout[v]+1, -pLen);
            cntBIT.get(pColor).add(tout[v]+1, -1);
        }
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) {
            if ((diff & (1<<k)) != 0) u = up[k][u];
        }
        if (u == v) return u;
        for (int k = LOG-1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }
        return up[0][u];
    }

    static long querySum(int node, int color) {
        return sumBIT.get(color).sum(tin[node]);
    }
    static long queryCnt(int node, int color) {
        return cntBIT.get(color).sum(tin[node]);
    }
}

