        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, color;
        long len;
        Edge(int to, int color, long len) {
            this.to = to;
            this.color = color;
            this.len = len;
        }
    }

    static class QueryPoint {
        int color, qid, sign;
        QueryPoint(int color, int qid, int sign) {
            this.color = color;
            this.qid = qid;
            this.sign = sign;
        }
    }

    static int N, Q, LOG;
    static ArrayList<Edge>[] g;
    static int[][] parent;
    static int[] depth;
    static int[] tin, tout;
    static long[] dist;
    static int timer = 0;

    static int[] qx, qu, qv, qlca;
    static long[] qy, ans;
    static ArrayList<QueryPoint>[] at;

    static long[] colorCount;
    static long[] colorSum;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        Q = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            long d = fs.nextInt();
            g[a].add(new Edge(b, c, d));
            g[b].add(new Edge(a, c, d));
        }

        LOG = 1;
        while ((1 << LOG) <= N) LOG++;

        parent = new int[LOG][N + 1];
        depth = new int[N + 1];
        tin = new int[N + 1];
        tout = new int[N + 1];
        dist = new long[N + 1];

        buildTreeIterative(1);

        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= N; v++) {
                parent[k][v] = parent[k - 1][ parent[k - 1][v] ];
            }
        }

        qx = new int[Q];
        qu = new int[Q];
        qv = new int[Q];
        qlca = new int[Q];
        qy = new long[Q];
        ans = new long[Q];

        at = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) at[i] = new ArrayList<>();

        for (int i = 0; i < Q; i++) {
            int x = fs.nextInt();
            long y = fs.nextInt();
            int u = fs.nextInt();
            int v = fs.nextInt();

            qx[i] = x;
            qy[i] = y;
            qu[i] = u;
            qv[i] = v;
            qlca[i] = lca(u, v);

            ans[i] = dist[u] + dist[v] - 2L * dist[qlca[i]];

            at[u].add(new QueryPoint(x, i, +1));
            at[v].add(new QueryPoint(x, i, +1));
            at[qlca[i]].add(new QueryPoint(x, i, -2));
        }

        colorCount = new long[N + 1];
        colorSum = new long[N + 1];

        processQueriesDFS(1);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static void buildTreeIterative(int root) {
        int[] stack = new int[2 * N];
        int[] par = new int[N + 1];
        int[] idx = new int[N + 1];
        int top = 0;
        stack[top++] = root;
        par[root] = 0;
        depth[root] = 0;
        dist[root] = 0;

        while (top > 0) {
            int v = stack[top - 1];
            if (idx[v] == 0) {
                tin[v] = ++timer;
            }
            if (idx[v] < g[v].size()) {
                Edge e = g[v].get(idx[v]++);
                if (e.to == par[v]) continue;
                par[e.to] = v;
                parent[0][e.to] = v;
                depth[e.to] = depth[v] + 1;
                dist[e.to] = dist[v] + e.len;
                stack[top++] = e.to;
            } else {
                tout[v] = timer;
                top--;
            }
        }
    }

    static boolean isAncestor(int a, int b) {
        return tin[a] <= tin[b] && tout[b] <= tout[a];
    }

    static int lca(int a, int b) {
        if (isAncestor(a, b)) return a;
        if (isAncestor(b, a)) return b;
        for (int k = LOG - 1; k >= 0; k--) {
            if (parent[k][a] != 0 && !isAncestor(parent[k][a], b)) {
                a = parent[k][a];
            }
        }
        return parent[0][a];
    }

    static void processQueriesDFS(int root) {
        class State {
            int v, p, stage;
            Edge inEdge;
            State(int v, int p, int stage, Edge inEdge) {
                this.v = v;
                this.p = p;
                this.stage = stage;
                this.inEdge = inEdge;
            }
        }

        ArrayDeque<State> st = new ArrayDeque<>();
        st.push(new State(root, 0, 0, null));

        while (!st.isEmpty()) {
            State cur = st.pop();
            int v = cur.v;

            if (cur.stage == 0) {
                if (cur.inEdge != null) {
                    colorCount[cur.inEdge.color]++;
                    colorSum[cur.inEdge.color] += cur.inEdge.len;
                }

                for (QueryPoint qp : at[v]) {
                    long cnt = colorCount[qp.color];
                    long sum = colorSum[qp.color];
                    ans[qp.qid] += (long) qp.sign * (cnt * qy[qp.qid] - sum);
                }

                st.push(new State(v, cur.p, 1, cur.inEdge));
                List<Edge> edges = g[v];
                for (int i = edges.size() - 1; i >= 0; i--) {
                    Edge e = edges.get(i);
                    if (e.to == cur.p) continue;
                    st.push(new State(e.to, v, 0, e));
                }
            } else {
                if (cur.inEdge != null) {
                    colorCount[cur.inEdge.color]--;
                    colorSum[cur.inEdge.color] -= cur.inEdge.len;
                }
            }
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<vector<pair<int, pair<int, int>>>> adj(N + 1);
    vector<int> color_len(N); // color -> length

    for (int i = 0; i < N - 1; i++) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        adj[a].push_back({b, {c, d}});
        adj[b].push_back({a, {c, d}});
        color_len[c] = d;
    }

    // Preprocess parent, depth, dist from root
    vector<int> parent(N + 1), depth(N + 1);
    vector<long long> dist(N + 1, 0);
    vector<int> edge_color_to_parent(N + 1, 0);

    function<void(int, int)> dfs = [&](int u, int p) {
        parent[u] = p;
        for (auto &e : adj[u]) {
            int v = e.first;
            int c = e.second.first;
            int d = e.second.second;
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            dist[v] = dist[u] + d;
            edge_color_to_parent[v] = c;
            dfs(v, u);
        }
    };
    dfs(1, 0);

    // Precompute binary lifting for LCA
    int LOG = 20;
    vector<vector<int>> up(LOG, vector<int>(N + 1));
    for (int i = 1; i <= N; i++) up[0][i] = parent[i];
    for (int j = 1; j < LOG; j++) {
        for (int i = 1; i <= N; i++) {
            up[j][i] = up[j-1][up[j-1][i]];
        }
    }

    auto lca = [&](int u, int v) {
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if (diff & (1 << j)) u = up[j][u];
        }
        if (u == v) return u;
        for (int j = LOG - 1; j >= 0; j--) {
            if (up[j][u] != up[j][v]) {
                u = up[j][u];
                v = up[j][v];
            }
        }
        return parent[u];
    };

    auto count_color_on_path = [&](int u, int v, int color) {
        int w = lca(u, v);
        int cnt = 0;
        // from u up to w
        int x = u;
        while (x != w) {
            if (edge_color_to_parent[x] == color) cnt++;
            x = parent[x];
        }
        // from v up to w
        x = v;
        while (x != w) {
            if (edge_color_to_parent[x] == color) cnt++;
            x = parent[x];
        }
        return cnt;
    };

    while (Q--) {
        int x, y, u, v;
        cin >> x >> y >> u >> v;
        int w = lca(u, v);
        long long base_dist = dist[u] + dist[v] - 2 * dist[w];
        int cnt = count_color_on_path(u, v, x);
        long long ans = base_dist + cnt * (y - color_len[x]);
        cout << ans << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct QueryItem {
    int x, y, u, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<vector<tuple<int,int,int>>> g(N + 1); // to, color, length
    vector<int> ea(N), eb(N), ec(N), ed(N);
    for (int i = 1; i <= N - 1; ++i) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        ea[i] = a; eb[i] = b; ec[i] = c; ed[i] = d;
        g[a].push_back({b, c, d});
        g[b].push_back({a, c, d});
    }

    vector<QueryItem> queries(Q);
    vector<vector<pair<int,int>>> need(N + 1); 
    // need[v] = list of (color, query_id) to evaluate at vertex v

    for (int i = 0; i < Q; ++i) {
        int x, y, u, v;
        cin >> x >> y >> u >> v;
        queries[i] = {x, y, u, v};
        need[u].push_back({x, i});
        need[v].push_back({x, i});
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<int> depth(N + 1, 0);
    vector<ll> distRoot(N + 1, 0);
    vector<vector<int>> up(LOG, vector<int>(N + 1, 0));

    // iterative DFS for parent/depth/distRoot
    {
        vector<int> st = {1};
        up[0][1] = 0;
        depth[1] = 0;
        distRoot[1] = 0;
        vector<int> parent(N + 1, -1);
        parent[1] = 0;

        while (!st.empty()) {
            int v = st.back();
            st.pop_back();
            for (auto [to, col, len] : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                up[0][to] = v;
                depth[to] = depth[v] + 1;
                distRoot[to] = distRoot[v] + len;
                st.push_back(to);
            }
        }
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            int p = up[k - 1][v];
            up[k][v] = (p == 0 ? 0 : up[k - 1][p]);
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; ++k) {
            if (diff & (1 << k)) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    };

    vector<int> w(Q);
    for (int i = 0; i < Q; ++i) {
        w[i] = lca(queries[i].u, queries[i].v);
        need[w[i]].push_back({queries[i].x, i});
    }

    vector<ll> valU(Q), valV(Q), valW(Q);

    // DFS with enter/exit events while maintaining:
    // cnt[color] = number of edges of this color on root->current path
    // sum[color] = sum of original lengths of edges of this color on root->current path
    vector<ll> cnt(N + 1, 0), sum(N + 1, 0);

    struct State {
        int v, p;
        int colorFromParent, lenFromParent;
        int type; // 0 enter, 1 exit
    };

    vector<State> st;
    st.push_back({1, 0, 0, 0, 0});

    while (!st.empty()) {
        State cur = st.back();
        st.pop_back();

        int v = cur.v, p = cur.p;

        if (cur.type == 0) {
            if (p != 0) {
                cnt[cur.colorFromParent]++;
                sum[cur.colorFromParent] += cur.lenFromParent;
            }

            for (auto [color, qid] : need[v]) {
                ll adjusted = distRoot[v] - sum[color] + cnt[color] * 1LL * queries[qid].y;
                if (v == queries[qid].u) valU[qid] = adjusted;
                else if (v == queries[qid].v) valV[qid] = adjusted;
                else valW[qid] = adjusted; // this is LCA
            }

            st.push_back({v, p, cur.colorFromParent, cur.lenFromParent, 1});
            for (auto [to, color, len] : g[v]) {
                if (to == p) continue;
                st.push_back({to, v, color, len, 0});
            }
        } else {
            if (p != 0) {
                cnt[cur.colorFromParent]--;
                sum[cur.colorFromParent] -= cur.lenFromParent;
            }
        }
    }

    for (int i = 0; i < Q; ++i) {
        ll ans = valU[i] + valV[i] - 2LL * valW[i];
        cout << ans << '\n';
    }

    return 0;
}
